PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?deathDate
WHERE {
  VALUES ?film { dbr:Karin_Daughter_of_Ingmar dbr:The_Man_in_the_Trunk }

  # director (prefer dbp:director)
  OPTIONAL { ?film dbp:director ?dirDBP . }
  OPTIONAL { ?film dbo:director ?dirDBO . }
  BIND (COALESCE(?dirDBP, ?dirDBO) AS ?director)

  # director's death date (prefer dbp:deathDate)
  OPTIONAL { ?director dbp:deathDate ?deathDBP . }
  OPTIONAL { ?director dbo:deathDate ?deathDBO . }
  BIND (COALESCE(?deathDBP, ?deathDBO) AS ?deathDate)

  # optional labels for readability
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER (lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER (lang(?directorLabel) = "en") }
}
LIMIT 100
